<?php
namespace Modules\Analytics\Controllers\Web;
use Core\http\ResponseFactory;use Modules\Analytics\Services\UserPointService;use Modules\System\Services\SiteAdminAccess;use RuntimeException;
final class AdminPointController{public function __construct(private UserPointService$s){}public function index(){return$this->run(fn()=>['success'=>true,'data'=>$this->s->index((int)auth()->id())]);}public function store(){return$this->run(fn()=>['success'=>true,'data'=>['id'=>$this->admin(fn()=>$this->s->store((int)auth()->id(),$this->payload()))]]);}public function update(int$id){return$this->run(function()use($id){$this->admin(fn()=>$this->s->update((int)auth()->id(),$id,$this->payload()));return['success'=>true];});}public function delete(int$id){return$this->run(function()use($id){$this->admin(fn()=>$this->s->delete((int)auth()->id(),$id));return['success'=>true];});}private function admin(callable$c):mixed{if(!SiteAdminAccess::allows(auth()->user()))throw new RuntimeException('فقط مدیر سایت اجازه مدیریت قوانین امتیاز را دارد.');return$c();}private function payload():array{$raw=base64_decode(strtr((string)request()->input('payload_b64',''),'-_','+/'),true);$d=$raw===false?null:json_decode($raw,true);if(!is_array($d))throw new RuntimeException('اطلاعات قانون معتبر نیست.');return$d;}private function run(callable$c){try{return ResponseFactory::json($c());}catch(\Throwable$e){return ResponseFactory::json(['success'=>false,'message'=>$e->getMessage()],422);}}}
